properties.property:
[
{
   "text": "You come across a clearing nestled into a grove. A dozen swords are lined up, each stuck into a stone. Each sword's blade shimmers with a different color of mana on each edge. If you have enough mana shards, you can break the enchantments keeping them stuck and take them for yourself.",
   "options": [{
      "name": "(Continue)", "action": [{"deleteMapObject":-1}]}]
}
]

[
  {
    "text": "You see the sword of Fire and Ice stuck into the stone here.",
    "options": [
      {
        "name": "Pull it forth. (Spend 50 mana shards)",
        "condition": [
          { "hasShards": 50 }
        ],
        "text": "'You pull the sword free, raising it into the air with a smile.'",
        "action": [
          {
            "addShards": -50,
            "grantRewards": [
              { "type": "card", "cardName": "Sword of Fire and Ice", "count": 1 }
            ],
		"deleteMapObject":-1
          }
        ]
      },
      {
        "name": "Pull it forth. (Spend 50 mana shards)",
        "condition": [
          { "hasShards": 50, "not": true }
        ],
        "text": "You lack the magical strength to pull out the sword.",
					"options": [ { "name": "(Continue)" } ]
      },
				{
					"name": "(Step away from the sword)",
					"text": "You step away from this sword for now.",
					"options": [ { "name": "(Continue)" } ]
				}
    ]
  }
]

